-- FINAGRO Web — budget versions, independent DRE/DFC projections and RLS.
begin;
create schema test_support;
create function test_support.assert_true(c boolean,m text) returns void language plpgsql set search_path='' as $$begin if c is not true then raise exception 'TEST FAILED: %',m; end if; end$$;
create function test_support.expect_error(q text,e text) returns void language plpgsql set search_path='' as $$declare m text;begin begin execute q;exception when others then m=sqlerrm;if position(e in m)=0 then raise exception 'TEST FAILED: expected %, got %',e,m;end if;return;end;raise exception 'TEST FAILED: expected %',e;end$$;
grant usage on schema test_support to authenticated;grant execute on all functions in schema test_support to authenticated;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at) values
('91000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','budget-a@example.test','x',now(),'{}','{}',now(),now()),
('91000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','budget-ro@example.test','x',now(),'{}','{}',now(),now()),
('92000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','budget-b@example.test','x',now(),'{}','{}',now(),now());
insert into public.organizations(id,legal_name) values('91000000-0000-0000-0000-000000000010','BUDGET A'),('92000000-0000-0000-0000-000000000020','BUDGET B');
select private.seed_default_roles('91000000-0000-0000-0000-000000000010','91000000-0000-0000-0000-000000000001');select private.seed_default_roles('92000000-0000-0000-0000-000000000020','92000000-0000-0000-0000-000000000001');
insert into public.memberships(organization_id,user_id,role_id) select '91000000-0000-0000-0000-000000000010','91000000-0000-0000-0000-000000000002',id from public.roles where organization_id='91000000-0000-0000-0000-000000000010' and name='Somente leitura';
insert into public.farms(id,organization_id,name) values('91000000-0000-0000-0000-000000000101','91000000-0000-0000-0000-000000000010','A1'),('91000000-0000-0000-0000-000000000102','91000000-0000-0000-0000-000000000010','A2'),('92000000-0000-0000-0000-000000000101','92000000-0000-0000-0000-000000000020','B1');
insert into public.crop_seasons(id,organization_id,name,season_type) values('91000000-0000-0000-0000-000000000201','91000000-0000-0000-0000-000000000010','Safra A','PRINCIPAL'),('92000000-0000-0000-0000-000000000201','92000000-0000-0000-0000-000000000020','Safra B','PRINCIPAL');
insert into public.allocation_rules(id,organization_id,crop_season_id,name,is_active) values('91000000-0000-0000-0000-000000000301','91000000-0000-0000-0000-000000000010','91000000-0000-0000-0000-000000000201','45/55',true);
insert into public.allocation_rule_items(organization_id,allocation_rule_id,farm_id,percentage) values('91000000-0000-0000-0000-000000000010','91000000-0000-0000-0000-000000000301','91000000-0000-0000-0000-000000000101',45),('91000000-0000-0000-0000-000000000010','91000000-0000-0000-0000-000000000301','91000000-0000-0000-0000-000000000102',55);
insert into public.allocation_rules(id,organization_id,crop_season_id,name,is_active) values('92000000-0000-0000-0000-000000000301','92000000-0000-0000-0000-000000000020','92000000-0000-0000-0000-000000000201','B 100',true);
insert into public.allocation_rule_items(organization_id,allocation_rule_id,farm_id,percentage) values('92000000-0000-0000-0000-000000000020','92000000-0000-0000-0000-000000000301','92000000-0000-0000-0000-000000000101',100);
insert into public.chart_accounts(id,organization_id,code,name,managerial_type,nature) values('92000000-0000-0000-0000-000000000999','92000000-0000-0000-0000-000000000020','B-ACCOUNT','Conta B','OUTRO','NEUTRA');

set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000001',true);
select public.apply_chart_account_template('91000000-0000-0000-0000-000000000010','3269e51b-12de-5887-a85c-4461af91b4e9');
select public.apply_reporting_template('91000000-0000-0000-0000-000000000010',(select id from public.reporting_templates where code='PROJECAO_DRE'));
select public.apply_reporting_template('91000000-0000-0000-0000-000000000010',(select id from public.reporting_templates where code='PROJECAO_DFC'));
create temporary table ids(version_id uuid,account_id uuid,is_source boolean default true);
insert into ids select public.create_budget_plan('91000000-0000-0000-0000-000000000010','Orçamento 2027','2027-01-01','2027-12-01','91000000-0000-0000-0000-000000000201','V1'),id from public.chart_accounts where organization_id='91000000-0000-0000-0000-000000000010' and code='FINAGRO-V1-G020-S001';
select test_support.assert_true((select count(*) from public.budgets where budget_version_id=(select version_id from ids))=2,'version owns DRE and DFC projections');
select public.replace_budget_projection_items('91000000-0000-0000-0000-000000000010',(select version_id from ids),'DRE',jsonb_build_array(jsonb_build_object('period_month','2027-01-01','chart_account_id',(select account_id from ids),'crop_season_id','91000000-0000-0000-0000-000000000201','farm_id','91000000-0000-0000-0000-000000000101','amount','1000.00'),jsonb_build_object('period_month','2027-02-01','chart_account_id',(select account_id from ids),'crop_season_id','91000000-0000-0000-0000-000000000201','allocation_rule_id','91000000-0000-0000-0000-000000000301','amount','100.01')));
select public.replace_budget_projection_items('91000000-0000-0000-0000-000000000010',(select version_id from ids),'DFC',jsonb_build_array(jsonb_build_object('period_month','2027-01-01','chart_account_id',(select account_id from ids),'crop_season_id','91000000-0000-0000-0000-000000000201','farm_id','91000000-0000-0000-0000-000000000101','amount','300.00'),jsonb_build_object('period_month','2027-02-01','chart_account_id',(select account_id from ids),'crop_season_id','91000000-0000-0000-0000-000000000201','farm_id','91000000-0000-0000-0000-000000000101','amount','700.00')));
select test_support.assert_true((select sum(amount) from public.budget_items i join public.budgets b on b.id=i.budget_id where b.budget_version_id=(select version_id from ids) and b.budget_type='DRE')=1100.01,'annual DRE total exact');
select test_support.assert_true((select amount from public.budget_items i join public.budgets b on b.id=i.budget_id where b.budget_version_id=(select version_id from ids) and b.budget_type='DRE' and period_month='2027-01-01')=1000 and (select amount from public.budget_items i join public.budgets b on b.id=i.budget_id where b.budget_version_id=(select version_id from ids) and b.budget_type='DFC' and period_month='2027-01-01')=300,'same month DRE and DFC remain distinct');
select test_support.assert_true((select sum(allocated_amount) from public.budget_item_allocations a join public.budget_items i on i.id=a.budget_item_id where i.amount=100.01)=100.01,'allocation rounding preserves cents');
select public.publish_budget_version('91000000-0000-0000-0000-000000000010',(select version_id from ids));
select test_support.expect_error($$update public.budget_items set amount=1 where budget_id in(select id from public.budgets where budget_version_id=(select version_id from ids))$$,'PUBLISHED_BUDGET_VERSION_IS_IMMUTABLE');
reset role;update public.allocation_rule_items set percentage=40 where allocation_rule_id='91000000-0000-0000-0000-000000000301' and farm_id='91000000-0000-0000-0000-000000000101';update public.allocation_rule_items set percentage=60 where allocation_rule_id='91000000-0000-0000-0000-000000000301' and farm_id='91000000-0000-0000-0000-000000000102';set constraints all immediate;set constraints all deferred;
select test_support.assert_true((select percentage from public.budget_item_allocations a join public.budget_items i on i.id=a.budget_item_id join public.budgets b on b.id=i.budget_id where b.budget_version_id=(select version_id from ids) and a.allocation_rule_id='91000000-0000-0000-0000-000000000301' and a.farm_id='91000000-0000-0000-0000-000000000101')=45,'published allocation snapshot survives rule changes');
set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000001',true);
insert into ids select public.copy_budget_version('91000000-0000-0000-0000-000000000010',(select version_id from ids where is_source),'Revisão Março'),account_id,false from ids where is_source;
select test_support.assert_true((select count(distinct version_id) from ids)=2,'version copied');
update public.budget_items set amount=999 where budget_id in(select id from public.budgets where budget_version_id=(select version_id from ids where not is_source));
select test_support.assert_true((select sum(amount) from public.budget_items i join public.budgets b on b.id=i.budget_id where b.budget_version_id=(select version_id from ids where is_source))<>999,'copied version independent');
select test_support.expect_error($$select public.replace_budget_projection_items('91000000-0000-0000-0000-000000000010',(select version_id from ids where not is_source),'DRE',jsonb_build_array(jsonb_build_object('period_month','2027-01-01','chart_account_id','92000000-0000-0000-0000-000000000999','farm_id','91000000-0000-0000-0000-000000000101','amount','1')))$$,'ACTIVE_CHART_ACCOUNT_NOT_FOUND_IN_ORGANIZATION');
select test_support.expect_error($$select public.replace_budget_projection_items('91000000-0000-0000-0000-000000000010',(select version_id from ids where not is_source),'DRE',jsonb_build_array(jsonb_build_object('period_month','2027-01-01','chart_account_id',(select account_id from ids limit 1),'farm_id','92000000-0000-0000-0000-000000000101','amount','1')))$$,'ACTIVE_FARM_NOT_FOUND_IN_ORGANIZATION');
select test_support.expect_error($$select public.replace_budget_projection_items('91000000-0000-0000-0000-000000000010',(select version_id from ids where not is_source),'DRE',jsonb_build_array(jsonb_build_object('period_month','2027-01-01','chart_account_id',(select account_id from ids limit 1),'crop_season_id','92000000-0000-0000-0000-000000000201','farm_id','91000000-0000-0000-0000-000000000101','amount','1')))$$,'BUDGET_CROP_SEASON_NOT_FOUND');
select test_support.expect_error($$select public.replace_budget_projection_items('91000000-0000-0000-0000-000000000010',(select version_id from ids where not is_source),'DRE',jsonb_build_array(jsonb_build_object('period_month','2027-01-01','chart_account_id',(select account_id from ids limit 1),'crop_season_id','91000000-0000-0000-0000-000000000201','allocation_rule_id','92000000-0000-0000-0000-000000000301','amount','1')))$$,'ACTIVE_ALLOCATION_RULE_MUST_MATCH_BUDGET_SEASON');
insert into public.chart_accounts(id,organization_id,code,name,managerial_type,nature) values('91000000-0000-0000-0000-000000000999','91000000-0000-0000-0000-000000000010','UNMAPPED','Qualquer nome','OUTRO','NEUTRA');
select test_support.expect_error($$select public.replace_budget_projection_items('91000000-0000-0000-0000-000000000010',(select version_id from ids where not is_source),'DRE',jsonb_build_array(jsonb_build_object('period_month','2027-01-01','chart_account_id','91000000-0000-0000-0000-000000000999','farm_id','91000000-0000-0000-0000-000000000101','amount','1')))$$,'ACCOUNT_WITHOUT_MANAGERIAL_MAPPING');
select test_support.assert_true((select count(*) from public.chart_account_template_items i where i.code like 'FINAGRO-V1-G013%' or i.code='FINAGRO-V1-G025')=4 and not exists(select 1 from public.report_account_template_mappings m join public.reporting_templates t on t.id=m.reporting_template_id join public.chart_account_template_items i on i.id=m.chart_template_item_id where t.code in('PROJECAO_DRE','PROJECAO_DFC') and (i.code like 'FINAGRO-V1-G013%' or i.code='FINAGRO-V1-G025')),'four pending accounts remain unmapped');
reset role;select set_config('request.jwt.claim.sub','',true);set local role authenticated;select set_config('request.jwt.claim.role','authenticated',true);select set_config('request.jwt.claim.sub','91000000-0000-0000-0000-000000000002',true);
select test_support.assert_true((select count(*) from public.budget_plans)=1,'read-only can view own budget');
select test_support.expect_error($$select public.create_budget_plan('91000000-0000-0000-0000-000000000010','Ataque','2028-01-01','2028-12-01',null,'V1')$$,'PERMISSION_DENIED');
select test_support.expect_error($$select public.create_budget_plan('92000000-0000-0000-0000-000000000020','Cross','2028-01-01','2028-12-01',null,'V1')$$,'PERMISSION_DENIED');
select test_support.expect_error($$select public.copy_budget_version('92000000-0000-0000-0000-000000000020','92000000-0000-0000-0000-000000000777','Ataque')$$,'PERMISSION_DENIED');
select test_support.expect_error($$select public.publish_budget_version('92000000-0000-0000-0000-000000000020','92000000-0000-0000-0000-000000000777')$$,'PERMISSION_DENIED');
select test_support.assert_true((select count(*) from public.budget_plans where organization_id='92000000-0000-0000-0000-000000000020')=0,'A users cannot view B budgets');
rollback;
